            CURRENCY_WHITESPACE
        ).fetch_all(self.pool()).await?;
        let mut histories: Vec<MemberHistory> = Vec::new();
        for row in rows {
            let id = row
                .parliament_member_id
                .to_string()
                .parse::<MemberId>()
                .map_err(|error| EntityDetailsRepoError::DatabaseError(error.to_string()))?;
            if histories
                .last()
                .is_none_or(|history| history.member.id != id)
